int get_sock_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc;

    if (!sock || !sockaddr || !sockaddr_len)
        return -ENOTCONN;

    vcc = (struct atm_vcc *)sock->sk;

    if (!vcc || (!peer && !vcc->sap) || (peer && !vcc->pvc))
        return -ENOTCONN;

    memset(sockaddr, 0, sizeof(*sockaddr));
    sockaddr->sa_family = AF_ATMPVC;

    if (peer) {
        struct sockaddr_pvc *pvc = (struct sockaddr_pvc *)sockaddr;
        pvc->pvc_number = vcc->pvc;
        pvc->address_family = AF_ATMPVC;
        pvc->if_num = vcc->if;
    } else {
        struct sockaddr_pvc *pvc = (struct sockaddr_pvc *)sockaddr;
        pvc->pvc_number = vcc->sap->sap_addr;
        pvc->address_family = AF_ATMPVC;
        pvc->if_num = vcc->if;
    }

    *sockaddr_len = sizeof(struct sockaddr_pvc);
    return 0;
}

int get_socket_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc;

    if (sock == NULL || sockaddr == NULL || sockaddr_len == NULL)
        return -ENOTCONN;

    vcc = ATM_SD(sock);
    if (!vcc || (!peer && !vcc->iocnt) || (peer && !vcc->iocnt))
        return -ENOTCONN;

    ((struct sockaddr_atmpvc *)sockaddr)->sacom.len = sizeof(*sockaddr);
    ((struct sockaddr_atmpvc *)sockaddr)->sacom/address_family = AF_ATMPVC;
    ((struct sockaddr_atmpvc *)sockaddr)->interface = vcc->dev->number;
    ((struct sockaddr_atmpvc *)sockaddr)->vpi = vcc->vpi;
    ((struct sockaddr_atmpvc *)sockaddr)->vci = vcc->vci;

    *sockaddr_len = sizeof(*sockaddr);
    return 0;
}

