int get_socket_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer)
{
    struct atm_vcc *vcc = sock->sk.atm_vcc;
    struct sockaddr_atm *saatm = (struct sockaddr_atm *)sockaddr;

    if (!vcc || (peer && !vcc->remote) || (!peer && !vcc->local))
        return -ENOTCONN;

    if (peer) {
        memcpy(&saatm->address, &vcc->remote, sizeof(vcc->remote));
    } else {
        memcpy(&saatm->address, &vcc->local, sizeof(vcc->local));
    }

    saatm->sacom.len = sizeof(*saatm);
    *sockaddr_len = sizeof(*saatm);
    return 0;
}

#include <linux/atmdev.h>
#include <linux/sockios.h>
#include <asm/errno.h>

int get_sockaddr_atm(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer)
{
    struct atm_vcc *vcc = sock->sk->sk_user_data;

    if (!vcc || vcc->vci == ATM_VCI_UNSPEC || vcc->vpi == ATM_VPI_UNSPEC)
        return -ENOTCONN;

    ((struct sockaddr_atmpvc *)sockaddr)->saph_addr.hu_vcc = vcc->vci;
    ((struct sockaddr_atmpvc *)sockaddr)->saph_addr.hu_vpi = vcc->vpi;
    ((struct sockaddr_atmpvc *)sockaddr)->saph_len = sizeof(struct sockaddr_atmpvc);
    ((struct sockaddr_atmpvc *)sockaddr)->saph_family = AF_ATMPVC;

    *sockaddr_len = sizeof(struct sockaddr_atmpvc);
    return 0;
}
